const details={tours:{k:'A JOURNEY THAT FEELS LIKE YOU',t:'Choose your island rhythm.',body:'<p>Start with an idea. We can shape the details around your interests.</p><ul><li><strong>Coast & calm:</strong> easy beach days and coastal exploring.</li><li><strong>Hills & heritage:</strong> tea country, cultural stops, and scenic journeys.</li><li><strong>Nature & discovery:</strong> a mix of wildlife, landscapes, and time outdoors.</li></ul><p>These are starting points for your inquiry, rather than fixed bookable packages.</p>',interest:0},transfer:{k:'FROM ARRIVAL TO ADVENTURE',t:'Plan your airport transfer.',body:'<p>Add your arrival airport, flight date, destination, passenger count, and luggage needs to your inquiry. These details help shape the transfer request.</p><p>Transfers and pricing are not confirmed through this preview.</p>',interest:3},photo:{k:'TAKE THE SCENIC ROUTE',t:'Bring your curiosity. And your camera.',body:'<p>Build your travel wish list around landscapes, wildlife, coastal scenes, or everyday island life.</p><p>Tell us what you enjoy photographing and your preferred pace. Specific locations and arrangements can be discussed when trip inquiries are connected.</p>',interest:2},guide:{k:'YOUR TRAVEL NOTEBOOK',t:'A little preparation goes a long way.',body:'<ul><li>Plan time to enjoy each stop instead of packing every day with travel.</li><li>Bring light layers, sun protection, and comfortable walking shoes.</li><li>Include modest clothing for visits to religious places.</li><li>Confirm current entry requirements and seasonal conditions before booking.</li></ul><p>Add any questions to your inquiry so your itinerary can reflect your needs.</p>',interest:0}};const dialog=document.querySelector('dialog');let selected=0;document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',()=>{const d=details[b.dataset.detail];selected=d.interest;document.querySelector('#dialog-kicker').textContent=d.k;document.querySelector('#dialog-title').textContent=d.t;document.querySelector('#dialog-content').innerHTML=d.body;dialog.showModal()}));document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('#dialog-plan').onclick=()=>{dialog.close();document.querySelector('select').selectedIndex=selected;document.querySelector('#inquiry').scrollIntoView({behavior:'smooth'});document.querySelector('input').focus({preventScroll:true})};document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const text=`CEYLON VOYAGERS — INQUIRY DRAFT\n\nName: ${d.get('name')}\nEmail: ${d.get('email')}\nInterest: ${d.get('interest')}\nTravel date: ${d.get('date')||'Flexible'}\n\n${d.get('message')}\n\nThis draft has not been sent.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='ceylon-voyagers-inquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Your inquiry draft has been downloaded. It has not been sent.'});

