function chooseItinerary(index,scrollCard=false){itineraryIndex=index;const itinerary=itineraryData[index];document.querySelector('.itinerary-plan').setAttribute('href','tours/'+itinerary.slug+'.html');document.querySelector('.itinerary-duration').textContent=itinerary.days+' · suggested journey';document.querySelector('.itinerary-tag').textContent=itinerary.tag;document.querySelector('.itinerary-name').textContent=itinerary.name;document.querySelector('.itinerary-description').textContent=itinerary.description;itineraryButtons.forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',String(i===index));});const stopList=document.querySelector('.itinerary-stops');stopList.replaceChildren();itinerary.stops.forEach((name,i)=>{if(i){const arrow=document.createElement('i');arrow.textContent='→';arrow.setAttribute('aria-hidden','true');stopList.append(arrow);}const stop=document.createElement('span');stop.textContent=(i+1)+'. '+name;stopList.append(stop);});const notes=document.querySelector('.itinerary-route-notes');notes.replaceChildren(...itinerary.notes.map(note=>{const li=document.createElement('li');li.textContent=note;return li;}));const coordinates=itinerary.stops.map(name=>itineraryProject(itineraryPoints[name]));document.querySelector('.itinerary-route-line').setAttribute('d',coordinates.map(([x,y],i)=>(i?'L':'M')+x.toFixed(1)+','+y.toFixed(1)).join(' '));const mapStops=document.querySelector('.itinerary-map-stops');mapStops.replaceChildren();const groups=[];coordinates.forEach(([x,y],i)=>{const group=groups.find(g=>Math.hypot(g.x-x,g.y-y)<13);if(group){group.numbers.push(i+1);group.names.push(itinerary.stops[i]);}else groups.push({x,y,numbers:[i+1],names:[itinerary.stops[i]]});});groups.forEach(g=>{const circle=itinerarySvg('circle',{cx:g.x,cy:g.y,r:5});const title=itinerarySvg('title',{});title.textContent=g.names.join(' / ');circle.append(title);mapStops.append(circle);const left=g.x<180;const label=itinerarySvg('text',{x:g.x+(left?-11:11),y:g.y+3,'text-anchor':left?'end':'start'});label.textContent=g.numbers.join('·')+' '+[...new Set(g.names)].join(' / ');if(label.textContent.length>24)label.textContent=g.numbers.join('·')+' South coast';mapStops.append(label);});document.querySelector('.sri-lanka-route-map').setAttribute('aria-label',itinerary.name+' route: '+itinerary.stops.join(' to '));const background=document.querySelector('.itinerary-backdrop img'),request=++itineraryBackgroundRequest;const preload=new Image();preload.onload=()=>{if(request!==itineraryBackgroundRequest)return;background.style.opacity='0';setTimeout(()=>{if(request!==itineraryBackgroundRequest)return;background.src=itinerary.image;background.style.opacity='.36';},matchMedia('(prefers-reduced-motion: reduce)').matches?0:250);};preload.src=itinerary.image;if(scrollCard&&matchMedia('(max-width:640px)').matches)itineraryButtons[index].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest',inline:'center'});}
